    // Minimal custom serializer for null values
    public static class NullSerializer implements JsonSerializer<String> {
        @Override
        public JsonElement serialize(String src, Type typeOfSrc, JsonSerializationContext context) {
            return new JsonPrimitive("SERIALIZED_NULL");
        }
    }

    // Minimal custom deserializer for JSON null
    public static class NullDeserializer implements JsonDeserializer<String> {
        @Override
        public String deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context)
                throws JsonParseException {
            return "DESERIALIZED_NULL";
        }
    }

    // Test class for serialization with nullSafe=false
    public static class SerializeTestClass {
        @JsonAdapter(value = NullSerializer.class, nullSafe = false)
        public String field;
    }

