    public void testSerializerWithNullSafeFalse() {
        Gson gson = new Gson();
        SerializeTestClass obj = new SerializeTestClass();
        obj.field = null;

        String json = gson.toJson(obj);

        // Unpatched: Would output {"field":null}
        // Patched: Should output {"field":"SERIALIZED_NULL"}
        assertEquals("{\"field\":\"SERIALIZED_NULL\"}", json);
    }

