package com.google.gson.stream;

import org.junit.Test;
import java.io.IOException;
import java.io.StringWriter;
import static org.junit.Assert.*;

public class JsonWriterValueDoubleTest {

    @Test
    public void testValueDouble_NaN_LenientMode_ShouldNotThrow() throws IOException {
        // Test that in lenient mode, NaN is written without exception
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.setLenient(true);

        writer.beginArray();
        writer.value(Double.NaN);
        writer.endArray();

        writer.close();
        // In lenient mode, NaN should be written as "NaN"
        assertEquals("[NaN]", stringWriter.toString());
    }

    @Test
    public void testValueDouble_PositiveInfinity_LenientMode_ShouldNotThrow() throws IOException {
        // Test that in lenient mode, positive infinity is written without exception
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.setLenient(true);

        writer.beginArray();
        writer.value(Double.POSITIVE_INFINITY);
        writer.endArray();

        writer.close();
        // In lenient mode, positive infinity should be written as "Infinity"
        assertEquals("[Infinity]", stringWriter.toString());
    }

    @Test
    public void testValueDouble_NegativeInfinity_LenientMode_ShouldNotThrow() throws IOException {
        // Test that in lenient mode, negative infinity is written without exception
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.setLenient(true);

        writer.beginArray();
        writer.value(Double.NEGATIVE_INFINITY);
        writer.endArray();

        writer.close();
        // In lenient mode, negative infinity should be written as "-Infinity"
        assertEquals("[-Infinity]", stringWriter.toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueDouble_NaN_StrictMode_ShouldThrow() throws IOException {
        // Test that in strict mode, NaN throws IllegalArgumentException
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.setLenient(false);

        writer.beginArray();
        writer.value(Double.NaN); // Should throw
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueDouble_PositiveInfinity_StrictMode_ShouldThrow() throws IOException {
        // Test that in strict mode, positive infinity throws IllegalArgumentException
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.setLenient(false);

        writer.beginArray();
        writer.value(Double.POSITIVE_INFINITY); // Should throw
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueDouble_NegativeInfinity_StrictMode_ShouldThrow() throws IOException {
        // Test that in strict mode, negative infinity throws IllegalArgumentException
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.setLenient(false);

        writer.beginArray();
        writer.value(Double.NEGATIVE_INFINITY); // Should throw
    }

    @Test
    public void testValueDouble_FiniteValue_LenientMode_ShouldWriteNormally() throws IOException {
        // Test that finite values work correctly in lenient mode
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.setLenient(true);

        writer.beginArray();
        writer.value(123.456);
        writer.endArray();

        writer.close();
        assertEquals("[123.456]", stringWriter.toString());
    }

    @Test
    public void testValueDouble_FiniteValue_StrictMode_ShouldWriteNormally() throws IOException {
        // Test that finite values work correctly in strict mode
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.setLenient(false);

        writer.beginArray();
        writer.value(123.456);
        writer.endArray();

        writer.close();
        assertEquals("[123.456]", stringWriter.toString());
    }

    @Test
    public void testValueDouble_WithDeferredName_LenientMode_ShouldWriteNameBeforeNaN() throws IOException {
        // Test that deferred name is written before NaN value in lenient mode
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.setLenient(true);

        writer.beginObject();
        writer.name("value");
        writer.value(Double.NaN);
        writer.endObject();

        writer.close();
        // Should write the name "value" before NaN
        assertEquals("{\"value\":NaN}", stringWriter.toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueDouble_WithDeferredName_StrictMode_ShouldThrowAfterWritingName() throws IOException {
        // Test that deferred name is written before exception is thrown in strict mode
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.setLenient(false);

        writer.beginObject();
        writer.name("value");
        // This should write the deferred name "value" before throwing
        writer.value(Double.NaN);
    }

    @Test
    public void testValueDouble_ConsistencyWithValueNumber_LenientMode() throws IOException {
        // Test that value(double) and value(Number) behave consistently in lenient mode
        StringWriter stringWriter1 = new StringWriter();
        JsonWriter writer1 = new JsonWriter(stringWriter1);
        writer1.setLenient(true);

        StringWriter stringWriter2 = new StringWriter();
        JsonWriter writer2 = new JsonWriter(stringWriter2);
        writer2.setLenient(true);

        writer1.beginArray();
        writer2.beginArray();

        // Both should write NaN without exception
        writer1.value(Double.NaN);
        writer2.value(Double.valueOf(Double.NaN));

        writer1.endArray();
        writer2.endArray();

        writer1.close();
        writer2.close();

        assertEquals(stringWriter2.toString(), stringWriter1.toString());
        assertEquals("[NaN]", stringWriter1.toString());
    }
}

