package com.google.gson.internal.bind;

import com.google.gson.*;
import com.google.gson.annotations.JsonAdapter;
import com.google.gson.internal.ConstructorConstructor;
import com.google.gson.reflect.TypeToken;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonWriter;
import org.junit.Test;

import java.io.IOException;
import java.io.StringReader;
import java.io.StringWriter;
import java.util.Collections;
import java.util.Map;
import java.lang.reflect.Type;

import static org.junit.Assert.*;

public class JsonAdapterAnnotationTypeAdapterFactoryTest {

    /**
     * Test that when @JsonAdapter(nullSafe = false) is used with a JsonDeserializer,
     * the deserializer receives JsonNull and can transform it.
     * This test should fail before the patch (because nullSafe was ignored)
     * and pass after the patch.
     */
    @Test
    public void testJsonAdapterNullSafeFalseWithJsonDeserializer() {
        // Create a Gson instance with a custom TypeAdapterFactory that returns our deserializer
        // We'll use a custom class annotated with @JsonAdapter pointing to a wrapper that provides the deserializer
        Gson gson = new Gson();

        // Deserialize using a custom adapter that is annotated with @JsonAdapter(nullSafe = false)
        // We need to create a type that uses our deserializer via annotation
        // Since we cannot directly annotate a class with a deserializer instance,
        // we create a custom TypeAdapterFactory that returns our deserializer
        // and register it via @JsonAdapter on a dummy class.
        // However, the test should exercise the path in JsonAdapterAnnotationTypeAdapterFactory
        // where the instance is a JsonDeserializer.
        // We'll create a class annotated with @JsonAdapter that points to a custom
        // JsonDeserializer class (which we'll define as a static nested class).
        // The annotation's nullSafe attribute is set to false.
        TypeToken<MyClass> typeToken = TypeToken.get(MyClass.class);
        Map<Type, InstanceCreator<?>> instanceCreators = Collections.emptyMap();
        ConstructorConstructor constructorConstructor = new ConstructorConstructor(instanceCreators);
        JsonAdapterAnnotationTypeAdapterFactory factory = new JsonAdapterAnnotationTypeAdapterFactory(constructorConstructor);

        // Simulate the annotation on MyClass
        JsonAdapter annotation = MyClassWithAnnotation.class.getAnnotation(JsonAdapter.class);
        assertNotNull(annotation);
        assertFalse(annotation.nullSafe()); // nullSafe is false

        // Now get the type adapter via the factory's getTypeAdapter method (which is package-private)
        // We'll use reflection to invoke it.
        try {
            java.lang.reflect.Method getTypeAdapterMethod = JsonAdapterAnnotationTypeAdapterFactory.class
                    .getDeclaredMethod("getTypeAdapter", ConstructorConstructor.class, Gson.class, TypeToken.class, JsonAdapter.class);
            getTypeAdapterMethod.setAccessible(true);

            TypeAdapter<MyClass> adapter = (TypeAdapter<MyClass>) getTypeAdapterMethod.invoke(
                    factory,
                    constructorConstructor,
                    gson,
                    typeToken,
                    annotation
            );

            // Now test deserialization of null
            JsonReader reader = new JsonReader(new StringReader("null"));
            MyClass result = adapter.read(reader);

