        String content;
        CustomData(String content) {
            this.content = content;
        }
    }

    public static class CustomSerializer implements JsonSerializer<CustomData> {
        @Override
        public JsonElement serialize(CustomData src, Type typeOfSrc, JsonSerializationContext context) {
            JsonObject obj = new JsonObject();
            obj.addProperty("data", src == null ? "NULL_SERIALIZED" : src.content);
            return obj;
        }
    }

    public static class CustomDeserializer implements JsonDeserializer<CustomData> {
        @Override
        public CustomData deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) {
            if (json.isJsonNull()) {
                return new CustomData("NULL_DESERIALIZED");
            }
            return new CustomData(json.getAsJsonObject().get("data").getAsString());
        }
    }

    public static class SerializeTestClass {
        @JsonAdapter(value = CustomSerializer.class, nullSafe = false)
        public CustomData field;
    }

    public static class DeserializeTestClass {
        @JsonAdapter(value = CustomDeserializer.class, nullSafe = false)
        public CustomData field;
    }

    @Test
    public void testSerializerWithNullSafeFalse() {
        Gson gson = new Gson();
        SerializeTestClass obj = new SerializeTestClass();
        obj.field = null;

        String json = gson.toJson(obj);
        // Unpatched: {"field":null} (custom serializer not called)
        // Patched: {"field":{"data":"NULL_SERIALIZED"}} (custom serializer called)
        assertEquals("{\"field\":{\"data\":\"NULL_SERIALIZED\"}}", json);
    }

    @Test
    public void testDeserializerWithNullSafeFalse() {
        Gson gson = new Gson();
        String json = "{\"field\":null}";

        DeserializeTestClass obj = gson.fromJson(json, DeserializeTestClass.class);
        // Unpatched: field=null (custom deserializer not called)
        // Patched: field.content="NULL_DESERIALIZED" (custom deserializer called)
        assertNotNull(obj.field);
        assertEquals("NULL_DESERIALIZED", obj.field.content);
    }
}

