package com.google.gson.stream;

import org.junit.Test;
import java.io.IOException;
import java.io.StringWriter;
import static org.junit.Assert.*;

public class JsonWriterValueDoubleTest {

    @Test
    public void testValueDouble_NaN_LenientMode_ShouldNotThrow() throws IOException {
        // Test that in lenient mode, NaN is written without exception
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.setLenient(true);

        writer.beginArray();
        writer.value(Double.NaN);
        writer.endArray();

        writer.close();
        // In lenient mode, NaN should be written as "NaN"
        assertEquals("[NaN]", stringWriter.toString());
    }

    @Test
    public void testValueDouble_PositiveInfinity_LenientMode_ShouldNotThrow() throws IOException {
        // Test that in lenient mode, positive infinity is written without exception
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.setLenient(true);

        writer.beginArray();
        writer.value(Double.POSITIVE_INFINITY);
        writer.endArray();

        writer.close();
        // In lenient mode, positive infinity should be written as "Infinity"
        assertEquals("[Infinity]", stringWriter.toString());
    }

    @Test
    public void testValueDouble_NegativeInfinity_LenientMode_ShouldNotThrow() throws IOException {
        // Test that in lenient mode, negative infinity is written without exception
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.setLenient(true);

        writer.beginArray();
        writer.value(Double.NEGATIVE_INFINITY);
        writer.endArray();

        writer.close();
        // In lenient mode, negative infinity should be written as "-Infinity"
        assertEquals("[-Infinity]", stringWriter.toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueDouble_NaN_StrictMode_ShouldThrow() throws IOException {
        // Test that in strict mode, NaN throws IllegalArgumentException
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.setLenient(false);

        writer.beginArray();
        writer.value(Double.NaN); // Should throw
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueDouble_PositiveInfinity_StrictMode_ShouldThrow() throws IOException {
        // Test that in strict mode, positive infinity throws IllegalArgumentException
        StringWriter stringWriter = new StringWriter();
        JsonWriter writer = new JsonWriter(stringWriter);
        writer.setLenient(false);

        writer.beginArray();
        writer.value(Double.POSITIVE_INFINITY); // Should throw
