package com.google.gson.internal.bind;

import com.google.gson.*;
import com.google.gson.annotations.JsonAdapter;
import com.google.gson.internal.ConstructorConstructor;
import com.google.gson.reflect.TypeToken;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonWriter;
import org.junit.Test;

import java.io.IOException;
import java.io.StringReader;
import java.io.StringWriter;
import java.util.Collections;
import java.util.Map;
import java.lang.reflect.Type;

import static org.junit.Assert.*;

public class JsonAdapterAnnotationTypeAdapterFactoryTest {

    /**
     * Test that when @JsonAdapter(nullSafe = false) is used with a JsonDeserializer,
     * the deserializer receives JsonNull and can transform it.
     * This test should fail before the patch (because nullSafe was ignored)
     * and pass after the patch.
     */
    @Test
    public void testJsonAdapterNullSafeFalseWithJsonDeserializer() {
        // Create a Gson instance with a custom TypeAdapterFactory that returns our deserializer
        // We'll use a custom class annotated with @JsonAdapter pointing to a wrapper that provides the deserializer
        Gson gson = new Gson();

        // Deserialize using a custom adapter that is annotated with @JsonAdapter(nullSafe = false)
        // We need to create a type that uses our deserializer via annotation
        // Since we cannot directly annotate a class with a deserializer instance,
        // we create a custom TypeAdapterFactory that returns our deserializer
        // and register it via @JsonAdapter on a dummy class.
        // However, the test should exercise the path in JsonAdapterAnnotationTypeAdapterFactory
        // where the instance is a JsonDeserializer.
        // We'll create a class annotated with @JsonAdapter that points to a custom
        // JsonDeserializer class (which we'll define as a static nested class).
        // The annotation's nullSafe attribute is set to false.
        TypeToken<MyClass> typeToken = TypeToken.get(MyClass.class);
        Map<Type, InstanceCreator<?>> instanceCreators = Collections.emptyMap();
        ConstructorConstructor constructorConstructor = new ConstructorConstructor(instanceCreators);
        JsonAdapterAnnotationTypeAdapterFactory factory = new JsonAdapterAnnotationTypeAdapterFactory(constructorConstructor);

        // Simulate the annotation on MyClass
        JsonAdapter annotation = MyClassWithAnnotation.class.getAnnotation(JsonAdapter.class);
        assertNotNull(annotation);
        assertFalse(annotation.nullSafe()); // nullSafe is false

        // Now get the type adapter via the factory's getTypeAdapter method (which is package-private)
        // We'll use reflection to invoke it.
        try {
            java.lang.reflect.Method getTypeAdapterMethod = JsonAdapterAnnotationTypeAdapterFactory.class
                    .getDeclaredMethod("getTypeAdapter", ConstructorConstructor.class, Gson.class, TypeToken.class, JsonAdapter.class);
            getTypeAdapterMethod.setAccessible(true);

            TypeAdapter<MyClass> adapter = (TypeAdapter<MyClass>) getTypeAdapterMethod.invoke(
                    factory,
                    constructorConstructor,
                    gson,
                    typeToken,
                    annotation
            );

            // Now test deserialization of null
            JsonReader reader = new JsonReader(new StringReader("null"));
            MyClass result = adapter.read(reader);

            // With nullSafe = false, the deserializer should be called and return the default object
            // Before the patch, nullSafe was ignored, so TreeTypeAdapter would have returned null.
            assertNotNull(result);
            assertEquals("default", result.value);
        } catch (Exception e) {
            fail("Reflection failed: " + e.getMessage());
        }
    }

    /**
     * Test that when @JsonAdapter(nullSafe = false) is used with a JsonSerializer,
     * the serializer is called with null value and can produce custom JSON.
     * This test should fail before the patch (because nullSafe was ignored)
     * and pass after the patch.
     */
    @Test
    public void testJsonAdapterNullSafeFalseWithJsonSerializer() throws IOException {
        Gson gson = new Gson();
        TypeToken<MyClass> typeToken = TypeToken.get(MyClass.class);
        Map<Type, InstanceCreator<?>> instanceCreators = Collections.emptyMap();
        ConstructorConstructor constructorConstructor = new ConstructorConstructor(instanceCreators);
        JsonAdapterAnnotationTypeAdapterFactory factory = new JsonAdapterAnnotationTypeAdapterFactory(constructorConstructor);

        // Use a different annotation that points to a serializer class with nullSafe = false
        JsonAdapter annotation = MyClassWithSerializerAnnotation.class.getAnnotation(JsonAdapter.class);
        assertNotNull(annotation);
        assertFalse(annotation.nullSafe());

        try {
            java.lang.reflect.Method getTypeAdapterMethod = JsonAdapterAnnotationTypeAdapterFactory.class
                    .getDeclaredMethod("getTypeAdapter", ConstructorConstructor.class, Gson.class, TypeToken.class, JsonAdapter.class);
            getTypeAdapterMethod.setAccessible(true);

            TypeAdapter<MyClass> adapter = (TypeAdapter<MyClass>) getTypeAdapterMethod.invoke(
                    factory,
                    constructorConstructor,
                    gson,
                    typeToken,
                    annotation
            );

            // Serialize null
            StringWriter stringWriter = new StringWriter();
            JsonWriter writer = new JsonWriter(stringWriter);
            adapter.write(writer, null);
            writer.close();

            // With nullSafe = false, the serializer should be called and produce "NULL_PLACEHOLDER"
            // Before the patch, nullSafe was ignored, so TreeTypeAdapter would have written JSON null.
            String json = stringWriter.toString();
            assertEquals("\"NULL_PLACEHOLDER\"", json);
        } catch (Exception e) {
            fail("Reflection failed: " + e.getMessage());
        }
    }

    /**
     * Test that default nullSafe = true works as before (null values are handled by the adapter).
     */
    @Test
    public void testJsonAdapterNullSafeTrueDefault() throws IOException {
        Gson gson = new Gson();
        TypeToken<MyClass> typeToken = TypeToken.get(MyClass.class);
        Map<Type, InstanceCreator<?>> instanceCreators = Collections.emptyMap();
        ConstructorConstructor constructorConstructor = new ConstructorConstructor(instanceCreators);
        JsonAdapterAnnotationTypeAdapterFactory factory = new JsonAdapterAnnotationTypeAdapterFactory(constructorConstructor);

        // Use an annotation with nullSafe = true (default)
        JsonAdapter annotation = MyClassWithNullSafeTrueAnnotation.class.getAnnotation(JsonAdapter.class);
        assertNotNull(annotation);
        assertTrue(annotation.nullSafe());

        try {
            java.lang.reflect.Method getTypeAdapterMethod = JsonAdapterAnnotationTypeAdapterFactory.class
                    .getDeclaredMethod("getTypeAdapter", ConstructorConstructor.class, Gson.class, TypeToken.class, JsonAdapter.class);
            getTypeAdapterMethod.setAccessible(true);

            TypeAdapter<MyClass> adapter = (TypeAdapter<MyClass>) getTypeAdapterMethod.invoke(
                    factory,
                    constructorConstructor,
                    gson,
                    typeToken,
                    annotation
            );

            // Deserialize null - should return null without calling the deserializer
            JsonReader reader = new JsonReader(new StringReader("null"));
            MyClass result = adapter.read(reader);
            assertNull(result);
        } catch (Exception e) {
            fail("Reflection failed: " + e.getMessage());
        }
    }

    // Helper class
    static class MyClass {
        String value;
        MyClass(String value) {
            this.value = value;
        }
    }

    // Class annotated with @JsonAdapter pointing to a deserializer with nullSafe = false
    @JsonAdapter(value = MyDeserializer.class, nullSafe = false)
    static class MyClassWithAnnotation {
        // dummy class
    }

    // Class annotated with @JsonAdapter pointing to a serializer with nullSafe = false
    @JsonAdapter(value = MySerializer.class, nullSafe = false)
    static class MyClassWithSerializerAnnotation {
        // dummy class
    }

    // Class annotated with @JsonAdapter pointing to a deserializer with nullSafe = true (default)
    @JsonAdapter(value = MyDeserializer.class, nullSafe = true)
    static class MyClassWithNullSafeTrueAnnotation {
        // dummy class
    }

    // Custom deserializer class (used by annotation)
    static class MyDeserializer implements JsonDeserializer<MyClass> {
        @Override
        public MyClass deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) throws JsonParseException {
            if (json.isJsonNull()) {
                return new MyClass("default");
            }
            return new MyClass(json.getAsString());
        }
    }

    // Custom serializer class (used by annotation)
    static class MySerializer implements JsonSerializer<MyClass> {
        @Override
        public JsonElement serialize(MyClass src, Type typeOfSrc, JsonSerializationContext context) {
            if (src == null) {
                return new JsonPrimitive("NULL_PLACEHOLDER");
            }
            return new JsonPrimitive(src.value);
        }
    }
}

